import{_ as o,o as s,c as a,a5 as n}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"格式化为 UTC+0 时间","description":"假设后端返回一个时间戳（例如以毫秒为单位的 Unix 时间戳，例如 1623456789000），你需要将其格式化为 UTC+0 时间。以下是使用原生 JavaScript 和 dayjs 库两种方式的实现方案。我将以当前时间戳（基于 2025 05 21 03:37 AM PD。","frontmatter":{"title":"格式化为 UTC+0 时间","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"假设后端返回一个时间戳（例如以毫秒为单位的 Unix 时间戳，例如 1623456789000），你需要将其格式化为 UTC+0 时间。以下是使用原生 JavaScript 和 dayjs 库两种方式的实现方案。我将以当前时间戳（基于 2025 05 21 03:37 AM PD。","sidebarWeight":138,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/日期/格式化为 UTC+0 时间.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/格式化为 UTC+0 时间.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/格式化为 UTC+0 时间.md"}'),e={name:"posts/JavaScript系统教程/03-对象、数组与函数/格式化为 UTC+0 时间.md"};function r(i,t,c,l,m,g){return s(),a("div",null,[...t[0]||(t[0]=[n('<div><h1 id="格式化为-utc-0-时间" tabindex="-1">格式化为 UTC+0 时间 <a class="header-anchor" href="#格式化为-utc-0-时间" aria-label="Permalink to &quot;格式化为 UTC+0 时间&quot;">​</a></h1><blockquote><p>本节目标：理解“格式化为 UTC+0 时间”的核心思路，并能把它用于实际开发或面试表达。 假设后端返回一个时间戳（例如以毫秒为单位的 Unix 时间戳，例如 1623456789000），你需要将其格式化为 UTC+0 时间。以下是使用原生 JavaScript 和 dayjs 库两种方式的实现方案。我将以当前时间戳（基于 2025-05-21 03:37 AM PDT）为例，并将其转换为 UTC+0 格式。</p></blockquote><p><strong>背景</strong></p><ul><li><strong>当前时间</strong>：2025-05-21 03:37 AM PDT（太平洋夏令时，UTC-7）。</li><li><strong>UTC+0 时间</strong>：需要转换为协调世界时（UTC），即比 PDT 早 7 小时。</li><li><strong>示例时间戳</strong>：假设后端返回 1716273420000（对应 2025-05-21 03:37:00 PDT，转换为 UTC 为 2025-05-21 10:37:00）。</li></ul><p><strong>1. 原生 JavaScript 处理</strong> _// 示例时间戳（毫秒）_const timestamp = 1716273420000; <em>// 2025-05-21 03:37:00 PDT</em> _// 使用 Date 对象解析时间戳_const date = new Date(timestamp); _// 格式化为 UTC+0 时间_const utcString = date.toUTCString(); _// 转换为 UTC 字符串，例如 &quot;Wed, 21 May 2025 10:37:00 GMT&quot;_const utcISOString = date.toISOString(); <em>// 转换为 ISO 格式，例如 &quot;2025-05-21T10:37:00.000Z&quot;</em> _// 自定义格式（例如 YYYY-MM-DD HH:mm:ss）_const pad = (num) =&gt; String(num).padStart(2, &#39;0&#39;);const year = date.getUTCFullYear();const month = pad(date.getUTCMonth() + 1); _// 月份从 0 开始_const day = pad(date.getUTCDate());const hours = pad(date.getUTCHours());const minutes = pad(date.getUTCMinutes());const seconds = pad(date.getUTCSeconds());const customFormat = <code>${year}-${month}-${day} ${hours}:${minutes}:${seconds}</code>; <em>// 例如 &quot;2025-05-21 10:37:00&quot;</em> console.log(&#39;UTC String:&#39;, utcString);console.log(&#39;UTC ISO String:&#39;, utcISOString);console.log(&#39;Custom Format:&#39;, customFormat); <strong>说明</strong></p><ul><li><strong>toUTCString()</strong>：返回 UTC 时间的标准字符串（如 Wed, 21 May 2025 10:37:00 GMT）。</li><li><strong>toISOString()</strong>：返回 ISO 格式的 UTC 时间（如 2025-05-21T10:37:00.000Z），常用于 API 交互。</li><li><strong>自定义格式</strong>：使用 getUTC* 方法（getUTCFullYear、getUTCMonth 等）提取 UTC 时间组件，手动拼接为 YYYY-MM-DD HH:mm:ss 格式。</li><li><strong>优点</strong>：无需额外库，适合简单场景。</li><li><strong>缺点</strong>：手动格式化繁琐，容易出错；不支持复杂格式化需求。</li></ul><p><strong>2. 使用 Dayjs 处理</strong><strong>安装 Dayjs</strong> 如果尚未安装 dayjs，运行以下命令： import dayjs from &#39;dayjs&#39;;import utc from &#39;dayjs/plugin/utc&#39;;import customParseFormat from &#39;dayjs/plugin/customParseFormat&#39;; _// 加载 UTC 和自定义格式插件_dayjs.extend(utc);dayjs.extend(customParseFormat); _// 示例时间戳（毫秒）_const timestamp = 1716273420000; <em>// 2025-05-21 03:37:00 PDT</em> _// 使用 dayjs 解析时间戳并转换为 UTC_const utcDate = dayjs.unix(timestamp / 1000).utc(); <em>// 转换为 UTC，timestamp 除以 1000 因为 dayjs.unix 接受秒</em> _// 格式化为 UTC 时间_const utcString = utcDate.format(&#39;ddd, DD MMM YYYY HH:mm:ss [GMT]&#39;); _// 例如 &quot;Wed, 21 May 2025 10:37:00 GMT&quot;_const utcISOString = utcDate.toISOString(); _// 例如 &quot;2025-05-21T10:37:00.000Z&quot;_const customFormat = utcDate.format(&#39;YYYY-MM-DD HH:mm:ss&#39;); <em>// 例如 &quot;2025-05-21 10:37:00&quot;</em> console.log(&#39;Dayjs UTC String:&#39;, utcString);console.log(&#39;Dayjs UTC ISO String:&#39;, utcISOString);console.log(&#39;Dayjs Custom Format:&#39;, customFormat); <strong>说明</strong></p><ul><li><strong>插件</strong>： <ul><li>utc：启用 UTC 模式，确保时间以 UTC+0 处理。</li><li>customParseFormat：支持自定义解析格式（这里未使用，但可扩展）。</li></ul></li><li><strong>dayjs.unix(timestamp / 1000)</strong>：将毫秒时间戳转换为秒，因为 dayjs.unix 接受秒单位。</li><li><strong>.utc()</strong>：将时间转换为 UTC+0。</li><li><strong>format()</strong>：使用字符串模板自定义格式： <ul><li>&#39;ddd, DD MMM YYYY HH:mm:ss [GMT]&#39; 模拟 toUTCString。</li><li>&#39;YYYY-MM-DD HH:mm:ss&#39; 提供简洁的自定义格式。</li></ul></li><li><strong>优点</strong>：格式化灵活，支持复杂日期格式；代码简洁；易于维护。</li><li><strong>缺点</strong>：需要安装额外库，增加项目依赖。</li></ul></div>',1)])])}const T=o(e,[["render",r]]);export{d as __pageData,T as default};
